from robot.api import logger
from ta_emil_cli_aatrace_parser.sack_downloader import SackFileNotLoadedToParser
import json


class EmilMessagesParser(object):
    """
    The Class is using for creating parsed messages
    param: unparsed_messages - generator - from emil_messages_reader
    param: messages_structures - dict - from message_structure_decoder
    """
    def __init__(self, unaprsed_messages):
        self.unparsed_messages = unaprsed_messages

    def get_all_parsed_messages(self, messages_structure):
        """
        :return: dict - which contains parsed_messages:
        {
        '426A': [426A_msg1, 426A_msg2... ],
        'XXXX,: [XXXX_msg1, XXXX_msg2...],
        .
        .
        .
        }
        """
        msg = {}
        for unparsed_msg in self.unparsed_messages:
            hex_id = unparsed_msg[4:8].upper()
            if hex_id not in msg:
                msg[hex_id] = []
            msg[hex_id].append(EmilMessagesParser._parse_single_type_messages(unparsed_msg, hex_id, messages_structure))
        return msg

    def get_single_type_parsed_messages(self, msg_hex_id, messages_structure):
        """

        :param msg_hex_id:
        :param messages_structure:
        :return:
        """
        try:
            single_type_parsed_messages = self.get_all_parsed_messages(messages_structure)[msg_hex_id.upper()]
        except SackFileNotLoadedToParser as exc:
            raise exc
        except:
            raise MsgDoesNotExistInTrace("msg {} does not exist in trace".format(msg_hex_id))
        else:
            return single_type_parsed_messages

    @staticmethod
    def _parse_single_type_messages(unparsed_msg, hex_id, messages_structure):
        """
        :return: dict - which contains parsed_messages:
        {
        [MSG_HEX_ID_msg1, MSG_HEX_ID_msg2... ]
        }
        """
        if not messages_structure:
            raise SackFileNotLoadedToParser('SACK file not loaded to parser! Check if you used proper tracing method !'
                                            'If KW Start BIN Trace Collection was used you are unable to parse msg')

        msg_name = EmilMessagesParser._get_msg_name_for_hex_if_exist(hex_id, messages_structure)
        if msg_name:
            single_parsed_msg = EmilMessagesParser.parse_message(unparsed_msg, messages_structure[msg_name])
            msg = EmilMessagesParser._get_all_fields_for_msg(single_parsed_msg)
            if messages_structure[msg_name]['total_length']*2 != len(unparsed_msg):
                msg['variable_length_payload'] = unparsed_msg[(messages_structure[msg_name]['total_length']*2):]
                logger.debug("Msg has fields with variable length, added to field: variable_length_payload")
        else:
            msg = unparsed_msg
        return msg

    @staticmethod
    def _get_all_fields_for_msg(single_parsed_msg):
        msg_fields = {}
        for single_field in single_parsed_msg:
            msg_fields[list(single_field.keys())[0]] = list(single_field.values())[0]
        return msg_fields

    @staticmethod
    def _get_msg_name_for_hex_if_exist(hex_id, messages_structure):
        for msg_name, single_msg_structure in list(messages_structure.items()):
            if hex_id in single_msg_structure['hex_id']:
                return msg_name
        return False

    @staticmethod
    def parse_message(unparsed_message, message_structure):
        """
        :param unparsed_message: generator - which contains unparsed messages
        :param message_structure: dict - from message_structure_decoder
        :return: generator - which contains single parsed messages, callable per single fields
        """
        for field_name, offset_length in list(message_structure['message_fields'].items()):
            offset = offset_length['offset'] * 2
            length = offset_length['length'] * 2
            yield EmilMessagesParser._read_single_field(unparsed_message, field_name, offset, length)

    @staticmethod
    def _read_single_field(unparsed_message, field_name, offset, length):
        return {field_name: unparsed_message[offset:offset + length]}

    @staticmethod
    def _verify_emil_msg_has_total_length_eq_to_total_length_from_sack_file_(message_total_length, unparsed_message):
        if message_total_length * 2 != len(unparsed_message):
            logger.debug("Problems with msg length: {msg_len}, emil_trace is not fully compatible with sack file:"
                         "len_from_sack: {msg_str_len}".format(msg_len=len(unparsed_message),
                                                               msg_str_len=str(message_total_length*2)))


class MsgDoesNotExistInTrace(Exception):
    """
    Exception MsgDoesNotExistInTrace
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)
